-- PT109-S4-Q12. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT109-S4-Q12$batch07$ AND q.stimulus=$batch07$Most adults in country X consume an increasing amount of fat as they grow older. However, for nearly all adults in country X, the percentage of fat in a person’s diet stays the same throughout adult life.$batch07$ AND q.prompt=$batch07$The statements above, if true, most strongly support which one of the following conclusions about adults in country X?$batch07$ AND q.correct_choice=$batch07$B$batch07$) THEN RAISE EXCEPTION 'Question changed: PT109-S4-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT109-S4-Q12$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S4-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT109-S4-Q12$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Most adults in country X eat more fat as they get older. But for nearly all of them, fat stays the same percentage of their diet.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer with numbers. Say fat is 20% of someone's diet. At 30, they eat 50 grams of fat, so 250 grams of food. At 60, they eat 80 grams of fat, still 20%, so 400 grams of food. If the fat goes up and its share stays fixed, the total has to go up too.$batch07$), (2, $batch07$Goal$batch07$, $batch07$They eat more food overall as they age.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT109-S4-Q12$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$We have no information about other countries.$batch07$), ($batch07$B$batch07$, $batch07$More fat at the same percentage means a bigger diet. "Generally" fits "most adults".$batch07$), ($batch07$C$batch07$, $batch07$Children's diets aren't mentioned.$batch07$), ($batch07$D$batch07$, $batch07$This is the most popular wrong answer. More food doesn't mean different *kinds* of food. Someone could eat bigger portions of the same five meals and fit the passage perfectly.$batch07$), ($batch07$E$batch07$, $batch07$If anything, eating more points toward gaining weight. Nothing supports losing it.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT109-S4-Q12$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
